def P(pid, title, invariant, varies, answer_rule, fipi, mistakes, style, kes=None, answer=None, **kw):
    """@proto для базы: номер задания берётся из id, паспорт КИМ — из TASK."""
    n = int(pid[2:4])
    kt, kes0, mins = TASK[n]
    kim = {'level': 'Б', 'points': 1, 'minutes': mins, 'kes': kes or kes0, 'kt': kt,
           'answer': answer or ANSWER.get(n, 'число'), 'style': style}
    kw.setdefault('lim', 10 ** 6)  # деньги, площади в см², население
    return proto(pid, EB, n, title, invariant, varies, answer_rule, fipi=fipi, mistakes=mistakes, kim=kim, **kw)


# ---------------------------------------------------------------- текст

NB = ' '


def T(x):
    """Число в условии: типографский минус, тысячи разделены пробелом (17 500), как в КИМ."""
    s = tnum(x)
    neg = s.startswith('−')
    s = s.lstrip('−')
    whole, _, frac = s.partition(',')
    if len(whole) > 4:
        whole = f'{int(whole):,}'.replace(',', NB)
    return ('−' if neg else '') + whole + (',' + frac if frac else '')


def pl(n, one, few, many):
    """«21 рубль», «3 рубля», «17 500 рублей»; для дробных — родительный падеж ед. ч. («2,5 литра»)."""
    x = F(n)
    if x.denominator != 1:
        return f'{T(x)} {few}'
    return f'{T(x)} {plural(int(x), one, few, many)}'


def rub(n):
    """Сумма денег: «250 рублей», «116 руб. 20 коп.»."""
    x = F(n)
    if x.denominator == 1:
        return pl(x, 'рубль', 'рубля', 'рублей')
    kop = int(x * 100) % 100
    return f'{T(int(x))} руб. {kop:02d} коп.'


def ceil(a, b=1):
    """Округление вверх для дробей: ceil(7, 3) = 3."""
    q = F(a) / F(b)
    return -((-q.numerator) // q.denominator)


def floor(a, b=1):
    q = F(a) / F(b)
    return q.numerator // q.denominator


def ap(x, d=2):
    """Приближённое значение для разбора: «8,02»."""
    return f'{float(x):.{d}f}'.replace('.', ',')


def dec(x):
    """Десятичная дробь в условии (без группировки тысяч)."""
    return tnum(x)


MEN = [('Артём', 'Артёма', 'Артёму'), ('Кирилл', 'Кирилла', 'Кириллу'), ('Тимур', 'Тимура', 'Тимуру'),
       ('Глеб', 'Глеба', 'Глебу'), ('Матвей', 'Матвея', 'Матвею'), ('Степан', 'Степана', 'Степану'),
       ('Роман', 'Романа', 'Роману'), ('Даниил', 'Даниила', 'Даниилу'), ('Фёдор', 'Фёдора', 'Фёдору'),
       ('Арсений', 'Арсения', 'Арсению'), ('Марк', 'Марка', 'Марку'), ('Лев', 'Льва', 'Льву')]
WOMEN = [('Вера', 'Веры', 'Вере'), ('Алёна', 'Алёны', 'Алёне'), ('Полина', 'Полины', 'Полине'),
         ('Ульяна', 'Ульяны', 'Ульяне'), ('Милана', 'Миланы', 'Милане'), ('Софья', 'Софьи', 'Софье'),
         ('Варвара', 'Варвары', 'Варваре'), ('Кира', 'Киры', 'Кире'), ('Злата', 'Златы', 'Злате'),
         ('Василиса', 'Василисы', 'Василисе'), ('Ева', 'Евы', 'Еве'), ('Таисия', 'Таисии', 'Таисии')]


class Who:
    """Персонаж: имя в падежах и глаголы прошедшего времени по роду: w.v('купил') → «купила»."""

    def __init__(self, r, male=None):
        self.male = r.random() < 0.5 if male is None else male
        self.n, self.g, self.d = r.choice(MEN if self.male else WOMEN)

    def v(self, verb):
        return verb if self.male else verb + 'а'


def ordw(k, case='nom_m'):
    """Порядковые числительные 1–12: ordw(3) → «третий», ordw(3, 'prep_m') → «третьем»."""
    base = ['', 'перв', 'втор', 'трет', 'четвёрт', 'пят', 'шест', 'седьм', 'восьм', 'девят', 'десят', 'одиннадцат',
            'двенадцат']
    b = base[k]
    if k == 3:
        return {'nom_m': 'третий', 'nom_f': 'третья', 'nom_n': 'третье', 'prep_m': 'третьем', 'gen_m': 'третьего',
                'acc_f': 'третью', 'ins_m': 'третьим', 'ins_f': 'третьей'}[case]
    hard = k in (2, 6, 7, 8)
    ends = {'nom_m': 'ой' if hard else 'ый', 'nom_f': 'ая', 'nom_n': 'ое', 'prep_m': 'ом', 'gen_m': 'ого', 'acc_f': 'ую',
            'ins_m': 'ым', 'ins_f': 'ой'}
    return b + ends[case]


