@P('eb01-ceil-capacity', 'Наименьшее число мест (автобусов, номеров) для группы',
   'Всех участников нужно разместить в одинаковые «ёмкости»: делим общее число людей на вместимость и округляем вверх.',
   'Сюжет (автобусы, байдарки, номера, столы, кабинки), состав группы, вместимость.',
   'ceil((N + M) / k)',
   r'наименьшее (число|количество) (палаток|комнат|шлюпок|автобусов|таких автобусов)',
   ['забыли прибавить сопровождающих', 'округлили вниз или взяли частное с остатком как ответ'],
   'Вопрос «Какое наименьшее число …», ответ — целое число без единиц.')
def gen_eb01_ceil_capacity(r):
    st = r.randrange(6)
    if st == 0:
        k = r.choice([18, 20, 22, 25, 28, 30])
        N, M = r.randint(80, 190), r.randint(6, 18)
        q = (f'На экскурсию в заповедник отправляются {pl(N, "школьник", "школьника", "школьников")} и '
             f'{pl(M, "учитель", "учителя", "учителей")}. Туристическая фирма предоставляет микроавтобусы, в каждом из которых '
             f'{pl(k, "пассажирское место", "пассажирских места", "пассажирских мест")}. Какое наименьшее число микроавтобусов '
             f'нужно заказать, чтобы вся группа выехала одновременно?')
    elif st == 1:
        k = r.choice([2, 3])
        N, M = r.randint(25, 70), r.randint(2, 6)
        q = (f'В байдарочном походе участвуют {pl(N, "турист", "туриста", "туристов")} и {pl(M, "инструктор", "инструктора", "инструкторов")}. '
             f'В одну байдарку садятся не больше {("двух", "трёх")[k - 2]} человек. Какое наименьшее число байдарок нужно взять '
             f'напрокат, чтобы в поход отправились все?')
    elif st == 2:
        k = r.choice([2, 3, 4])
        N, M = r.randint(30, 90), r.randint(3, 9)
        q = (f'На турнир по шахматам приезжают {pl(N, "спортсмен", "спортсмена", "спортсменов")} и '
             f'{pl(M, "тренер", "тренера", "тренеров")}. В одном гостиничном номере можно поселить не больше '
             f'{("двух", "трёх", "четырёх")[k - 2]} человек. Какое наименьшее число номеров нужно забронировать для всех приезжающих?')
    elif st == 3:
        k = r.choice([6, 8, 10, 12])
        N, M = r.randint(60, 180), r.randint(4, 14)
        q = (f'На юбилей фирмы пригласили {pl(N, "гостя", "гостей", "гостей")}, кроме того, в зале будут сидеть '
             f'{pl(M, "организатор", "организатора", "организаторов")}. За один стол можно посадить не больше '
             f'{pl(k, "человека", "человек", "человек")}. Какое наименьшее число столов нужно поставить в зале?')
    elif st == 4:
        k = r.choice([4, 6, 8])
        N, M = r.randint(40, 120), r.randint(3, 10)
        q = (f'Кабина канатной дороги поднимает не больше {pl(k, "пассажира", "пассажиров", "пассажиров")}. К подъёмнику подошли '
             f'{pl(N, "лыжник", "лыжника", "лыжников")} и {pl(M, "инструктор", "инструктора", "инструкторов")}. Какое наименьшее '
             f'число кабин понадобится, чтобы поднять на гору всех, если каждая кабина поднимается один раз?')
    else:
        k = r.choice([40, 45, 50, 60])
        N, M = r.randint(200, 600), r.randint(15, 60)
        q = (f'Со склада нужно вывезти {pl(N, "ящик", "ящика", "ящиков")} с яблоками и {pl(M, "ящик", "ящика", "ящиков")} с грушами. '
             f'В один фургон помещается не больше {pl(k, "ящика", "ящиков", "ящиков")}. Какое наименьшее число рейсов фургона '
             f'потребуется, чтобы вывезти все ящики?')
    tot = N + M
    if tot % k == 0:
        return None
    ans = ceil(tot, k)

    def chk():
        left, used = tot, 0
        while left > 0:
            left -= k
            used += 1
        return used == ans and (used - 1) * k < tot
    return pcard(q, num(ans), e=f'Всего {tot}; {tot} : {k} = {dec(F(tot, k)) if finite(F(tot, k)) else f"{tot // k} (ост. {tot % k})"}, '
                                  f'округляем вверх: {ans}.'), chk


CONS = [
    # (единица расхода, товар, упаковка) — расход r г на единицу, упаковка P кг
    'putty', 'feed', 'lawn', 'milk', 'paper', 'glue', 'tea',
]


@P('eb01-ceil-consumption', 'Наименьшее число упаковок при известном расходе',
   'Считаем общий расход (норма × количество × дни), переводим в единицы упаковки и округляем вверх.',
   'Материал (шпаклёвка, корм, семена, молоко, бумага, клей), нормы, размер упаковки, единицы (г/кг, мл/л).',
   'ceil(норма · количество · дни / упаковка)',
   r'(наименьшее|наименьшего) (число|количество) (банок|пакетиков|упаковок|пачек|килограммовых)|хватит на',
   ['не перевели граммы в килограммы', 'округлили вниз', 'забыли умножить на число дней'],
   'Вопрос «Какое наименьшее количество упаковок нужно купить/хватит на …», ответ — целое число.')
def gen_eb01_ceil_consumption(r):
    st = r.choice(CONS)
    if st == 'putty':
        rate = r.choice([400, 500, 600, 700, 800, 900, 1200])
        qty = r.randint(25, 140)
        pack = r.choice([5, 10, 20, 25])
        need, packs = F(rate * qty, 1000), pack
        q = (f'На выравнивание 1 кв. м стены уходит {rate} г шпаклёвки. Шпаклёвку продают в мешках по {pack} кг. Какое наименьшее '
             f'число мешков нужно купить, чтобы выровнять стены общей площадью {qty} кв. м?')
    elif st == 'feed':
        rate = r.choice([150, 200, 250, 300, 350, 400])
        dogs, days = r.randint(8, 30), r.choice([7, 10, 14, 30])
        pack = r.choice([10, 12, 15, 20])
        need, packs = F(rate * dogs * days, 1000), pack
        q = (f'В приюте живут {pl(dogs, "собака", "собаки", "собак")}. Каждой собаке в день полагается {rate} г сухого корма. '
             f'Корм продаётся в мешках по {pack} кг. Какого наименьшего числа мешков хватит приюту на {pl(days, "день", "дня", "дней")}?')
    elif st == 'lawn':
        rate = r.choice([25, 30, 35, 40, 45, 50])
        qty = r.randint(60, 400)
        pack = r.choice([1, 2, 5])
        need, packs = F(rate * qty, 1000), pack
        q = (f'Для посева газона требуется {rate} г семян на 1 кв. м. Семена газонной травы продаются в упаковках по {pack} кг. '
             f'Какое наименьшее количество упаковок нужно купить, чтобы засеять участок площадью {qty} кв. м?')
    elif st == 'milk':
        rate = r.choice([150, 200, 250, 300])
        kids, days = r.randint(40, 160), r.choice([5, 6, 10, 12])
        pack = r.choice([1, 2])
        need, packs = F(rate * kids * days, 1000), pack
        q = (f'В детском саду {pl(kids, "воспитанник", "воспитанника", "воспитанников")}, и каждому ежедневно дают {rate} мл молока. '
             f'Молоко закупают в пакетах по {pl(pack, "литру", "литра", "литров")}. Какое наименьшее число пакетов нужно закупить на '
             f'{pl(days, "день", "дня", "дней")}?')
        q = q.replace('по 1 литру', 'по 1 литру').replace('по 2 литра', 'по 2 литра')
    elif st == 'paper':
        rate = r.choice([180, 240, 260, 320, 350, 420, 650])
        days = r.randint(8, 25)
        pack = r.choice([250, 500])
        need, packs = rate * days, pack
        q = (f'За рабочий день в бухгалтерии расходуется {pl(rate, "лист", "листа", "листов")} бумаги. В одной пачке '
             f'{pl(pack, "лист", "листа", "листов")}. Какого наименьшего количества пачек хватит на {pl(days, "рабочий день", "рабочих дня", "рабочих дней")}?')
    elif st == 'glue':
        rate = r.choice([F(3, 2), F(5, 2), 3, F(7, 2), 4, 5])
        qty = r.randint(12, 60)
        pack = r.choice([20, 25])
        need, packs = rate * qty, pack
        q = (f'Для укладки 1 кв. м плитки требуется {dec(rate)} кг плиточного клея. Клей продают в мешках по {pack} кг. Какое '
             f'наименьшее число мешков нужно купить, чтобы уложить плитку на площади {qty} кв. м?')
    else:
        rate = r.choice([40, 45, 60, 75, 80, 90, 120])
        days = r.randint(3, 12)
        pack = r.choice([25, 50, 100])
        need, packs = rate * days, pack
        q = (f'Во время олимпиады в столовой ежедневно расходуется {pl(rate, "чайный пакетик", "чайных пакетика", "чайных пакетиков")}. '
             f'Олимпиада длится {pl(days, "день", "дня", "дней")}. В одной коробке {pl(pack, "пакетик", "пакетика", "пакетиков")}. '
             f'Какого наименьшего количества коробок хватит на все дни олимпиады?')
    if F(need) % packs == 0:
        return None
    ans = ceil(need, packs)
    if ans < 2 or ans > 400:
        return None

    def chk():
        # докупаем упаковки по одной, пока запаса не хватит
        k, stock = 0, F(0)
        while stock < need:
            stock += packs
            k += 1
        return k == ans
    return pcard(q, num(ans), e=f'Нужно {dec(need)}; {dec(need)} : {packs} ≈ {ap(F(need) / packs)}, округляем вверх: {ans}.'), chk


@P('eb01-floor-buy', 'Наибольшее число покупок на имеющиеся деньги (или время)',
   'Делим имеющуюся сумму (время) на цену одной штуки (время на одну штуку) и берём целую часть.',
   'Товар или работа (билеты, альбомы, детали на станке, страницы на принтере), цена, сумма, единицы времени.',
   'floor(M / p)',
   r'наибольшее (число|количество) (таких |пачек |страниц )?\w+ можно (купить|напечатать)',
   ['округлили вверх', 'не перевели минуты в секунды'],
   'Вопрос «Какое наибольшее число … можно …», ответ — целое число.')
def gen_eb01_floor_buy(r):
    st = r.randrange(5)
    if st < 3:
        p = r.randint(14, 95) if st < 2 else r.choice([120, 150, 180, 240, 260, 350, 450])
        M = r.choice([200, 300, 500, 1000]) if st < 2 else r.choice([2000, 3000, 5000])
        if M % p == 0 or M // p < 3:
            return None
        ans = M // p
        if st == 0:
            q = (f'На поездки по городу у школьника осталось {rub(M)}. Какое наибольшее число разовых билетов на трамвай по цене '
                 f'{rub(p)} за билет он может на них купить?')
        elif st == 1:
            q = (f'Для кружка рисования выделили {rub(M)}. Какое наибольшее количество альбомов для рисования по {rub(p)} за штуку '
                 f'удастся купить на эти деньги?')
        else:
            q = (f'Входной билет в планетарий стоит {rub(p)}. Классный руководитель собрал на поездку {rub(M)}. Какое наибольшее '
                 f'число билетов можно купить на эти деньги?')
        tot, unit = M, p
    else:
        s = r.choice([6, 7, 8, 9, 11, 12, 13, 14, 16, 18])
        m = r.randint(5, 30)
        if (60 * m) % s == 0:
            return None
        ans = 60 * m // s
        tot, unit = 60 * m, s
        if st == 3:
            q = (f'Станок штампует одну деталь за {pl(s, "секунду", "секунды", "секунд")}. Какое наибольшее число деталей он может '
                 f'изготовить за {pl(m, "минуту", "минуты", "минут")}?')
        else:
            q = (f'Копировальный аппарат делает одну копию за {pl(s, "секунду", "секунды", "секунд")}. Какое наибольшее число копий '
                 f'можно сделать на нём за {pl(m, "минуту", "минуты", "минут")}?')

    def chk():
        k, spent = 0, 0
        while spent + unit <= tot:
            spent += unit
            k += 1
        return k == ans
    return pcard(q, num(ans), e=f'{T(tot)} : {unit} = {tot // unit} (ост. {tot % unit}) — целых штук {ans}.'), chk


@P('eb01-promo', 'Акция «заплати за n — получи больше»',
   'Сначала считаем, сколько штук можно оплатить (целая часть), затем добавляем подарки за каждую полную «оплаченную» группу.',
   'Товар, цена, сумма, условия акции (2 → 3, 3 → 4, 4 → 5).',
   'k = floor(M / p); ответ k + floor(k / a)·b',
   r'заплатив за',
   ['не учли подарки', 'дали подарок за неполную группу'],
   'Вопрос «Сколько … можно получить на … рублей», ответ — целое число.')
def gen_eb01_promo(r):
    p = r.randint(18, 90)
    M = r.choice([150, 200, 250, 300, 400, 500, 600])
    a = r.choice([2, 3, 4])
    paid = M // p
    if paid < a + 1 or M % p == 0:
        return None
    ans = paid + paid // a
    item, items = r.choice([('йогурт', 'йогурта', 'йогуртов'), ('пирожок', 'пирожка', 'пирожков'),
                            ('воздушный шар', 'воздушных шара', 'воздушных шаров'), ('блокнот', 'блокнота', 'блокнотов'),
                            ('пакет сока', 'пакета сока', 'пакетов сока')])[0], None
    gen = {'йогурт': 'йогуртов', 'пирожок': 'пирожков', 'воздушный шар': 'воздушных шаров', 'блокнот': 'блокнотов',
           'пакет сока': 'пакетов сока'}[item]
    how = {2: 'за каждые два оплаченных', 3: 'за каждые три оплаченных', 4: 'за каждые четыре оплаченных'}[a]
    place = r.choice(['В пятницу в магазине у дома', 'В день открытия кафе', 'В выходные в киоске на набережной',
                      'Всю неделю в школьном буфете'])
    q = (f'{item.capitalize()} стоит {rub(p)}. {place} действует акция: {how} покупатель получает ещё один бесплатно. '
         f'Какое наибольшее число {gen} можно получить на {rub(M)} во время акции?')

    def chk():
        money, got, paid_ = M, 0, 0
        while money >= p:
            money -= p
            paid_ += 1
            got += 1
            if paid_ % a == 0:
                got += 1
        return got == ans
    return pcard(q, num(ans), e=f'Оплатить можно {paid} шт.; подарков {paid} : {a} → {paid // a}; всего {ans}.'), chk


@P('eb01-odd-bouquet', 'Наибольший букет из нечётного числа цветов',
   'Находим, сколько цветов можно купить (целая часть), и берём наибольшее нечётное число, не превосходящее его.',
   'Цветы, повод, цена одного цветка, сумма.',
   'k = floor(M / p); ответ k или k − 1 (нечётное)',
   r'нечётного числа цветов',
   ['не учли требование нечётности', 'округлили вверх'],
   'Вопрос «Из какого наибольшего числа … можно составить букет», ответ — целое число.')
def gen_eb01_odd_bouquet(r):
    p = r.choice([35, 40, 45, 55, 60, 65, 70, 75, 80, 90, 110, 120, 140, 150])
    M = r.choice([400, 500, 600, 700, 800, 1000, 1200, 1500, 2000])
    k = M // p
    if k % 2 == 1 or k < 4 or k > 40:
        return None
    ans = k - 1
    w = Who(r)
    fl, occ = r.choice([('хризантема', 'к юбилею бабушки'), ('роза', 'на выпускной вечер'), ('гербера', 'к празднику 8 Марта'),
                        ('гвоздика', 'к юбилею учительницы'), ('лилия', 'на день рождения мамы'), ('тюльпан', 'к дню рождения сестры')])
    fl_pl = {'хризантема': 'хризантем', 'роза': 'роз', 'гербера': 'гербер', 'гвоздика': 'гвоздик', 'лилия': 'лилий', 'тюльпан': 'тюльпанов'}[fl]
    q = (f'Поздравительный букет принято составлять из нечётного числа цветов. Одна {fl} стоит {rub(p)}. У {w.g} есть {rub(M)}. '
         f'Из какого наибольшего числа {fl_pl} {w.n} может собрать букет {occ}?')
    if fl == 'тюльпан':
        q = q.replace(f'Одна {fl}', 'Один тюльпан')

    def chk():
        best = max(x for x in range(1, 200, 2) if x * p <= M)
        return best == ans
    return pcard(q, num(ans), e=f'{M} : {p} → {k} цветов; {k} чётно, поэтому {ans}.'), chk


@P('eb01-change', 'Сдача с покупки',
   'Считаем стоимость покупки (цена × количество, плюс мелкие покупки) и вычитаем из отданной суммы.',
   'Покупка (топливо и вода, фрукты на вес, канцтовары, выпечка), цены, отданная купюра.',
   'X − (p·n + c)',
   r'сдачи',
   ['не перевели граммы в килограммы', 'забыли вторую покупку'],
   'Вопрос «Сколько рублей сдачи …», ответ — целое число рублей.')
def gen_eb01_change(r):
    st = r.randrange(4)
    w = Who(r)
    if st == 0:
        p = r.randint(52, 68)
        L = r.randint(12, 45)
        c = r.randint(40, 180)
        X = 5000 if p * L + c > 1900 else r.choice([2000, 5000])
        cost = p * L + c
        what = r.choice(['бутылку воды', 'кофе', 'омывающую жидкость', 'пачку влажных салфеток'])
        q = (f'Литр бензина на заправке стоит {rub(p)}. {w.n} {w.v("залил")} в бак {pl(L, "литр", "литра", "литров")} и '
             f'{w.v("купил")} {what} за {rub(c)}. За всё {w.n} {w.v("отдал")} кассиру {rub(X)}. Какую сдачу (в рублях) '
             f'{"он получит" if w.male else "она получит"}?')
        e = f'{p} · {L} + {c} = {cost}; {X} − {cost}.'
    elif st == 1:
        p = r.choice([120, 150, 160, 180, 220, 240, 250, 280, 320, 350, 450])
        kg, g = r.randint(1, 3), r.choice([100, 200, 250, 400, 500, 600, 750, 800])
        wgt = kg + F(g, 1000)
        cost = p * wgt
        if cost.denominator != 1:
            return None
        X = 1000 if cost < 1000 else 2000
        fr = r.choice([('черешни', 'черешню'), ('винограда', 'виноград'), ('мандаринов', 'мандарины'), ('сыра', 'сыр')])
        q = (f'На рынке {fr[0]} продают по {rub(p)} за килограмм. {w.n} {w.v("взял")} {kg} кг {g} г {fr[0]} и '
             f'{w.v("расплатил")}{"ся" if w.male else "ась"} купюрой в {rub(X)}. Какую сдачу в рублях {"он" if w.male else "она"} получит?')
        e = f'{kg} кг {g} г = {dec(wgt)} кг; {p} · {dec(wgt)} = {T(cost)}; {X} − {T(cost)}.'
    elif st == 2:
        a, n = r.randint(18, 60), r.randint(4, 12)
        b, m = r.randint(25, 90), r.randint(2, 5)
        cost = a * n + b * m
        X = r.choice([500, 1000]) if cost < 950 else 2000
        q = (f'Тетрадь стоит {rub(a)}, а ручка — {rub(b)}. {w.n} {w.v("купил")} {pl(n, "тетрадь", "тетради", "тетрадей")} и '
             f'{pl(m, "ручку", "ручки", "ручек")}. Сколько рублей сдачи {"он получит" if w.male else "она получит"} с {rub(X)}?')
        e = f'{a} · {n} + {b} · {m} = {cost}; {X} − {cost}.'
    else:
        a, n = r.randint(35, 95), r.randint(3, 8)
        b = r.randint(40, 150)
        cost = a * n + b
        X = r.choice([500, 1000]) if cost < 950 else 2000
        q = (f'В кафе булочка с корицей стоит {rub(a)}, а большой стакан какао — {rub(b)}. {w.n} {w.v("заказал")} '
             f'{pl(n, "булочку", "булочки", "булочек")} и один стакан какао и {w.v("расплатил")}{"ся" if w.male else "ась"} купюрой в {rub(X)}. '
             f'Какую сдачу в рублях {"он" if w.male else "она"} получит?')
        e = f'{a} · {n} + {b} = {cost}; {X} − {cost}.'
    ans = X - cost
    if ans <= 0:
        return None

    def chk():
        # отсчитываем сдачу, «набирая» покупку до отданной суммы
        return cost + F(ans) == X and ans > 0
    return pcard(q, num(ans), e=e), chk


@P('eb01-reverse', 'Обратная задача: по сдаче или списанию найти количество (цену)',
   'Из отданной суммы вычитаем сдачу (или известные покупки) и делим остаток на цену (или на число одинаковых товаров).',
   'Топливо до полного бака, одинаковые товары, списание с карты, остаток на телефоне; цены и суммы.',
   '(X − C) / p',
   r'получил[а]? \d+ рубл\w* сдачи|получила сдачу|списано|осталось \d+ рубл',
   ['разделили отданную сумму, а не потраченную', 'не вычли известные покупки'],
   'Вопрос «Сколько литров/минут …» или «Сколько стоит одна …», ответ — целое число.')
def gen_eb01_reverse(r):
    st = r.randrange(4)
    w = Who(r)
    if st == 0:
        p = r.randint(52, 69)
        L = r.randint(15, 48)
        X = r.choice([2000, 3000, 5000])
        C = X - p * L
        if C <= 0:
            return None
        ans = L
        q = (f'{w.n} {w.v("отдал")} кассиру автозаправки {rub(X)} и {w.v("попросил")} заправить машину до полного бака. Литр '
             f'бензина стоит {rub(p)}. Сдача составила {rub(C)}. Сколько литров бензина залили в бак?')
        e = f'({X} − {C}) : {p} = {L}.'
        chk = lambda: F(X - C, p) == ans
    elif st == 1:
        n = r.randint(3, 8)
        p = r.randint(40, 180)
        X = r.choice([500, 1000, 2000])
        C = X - n * p
        if C <= 0:
            return None
        ans = p
        thing = r.choice([('пирожных «картошка»', 'пирожное'), ('пакетов молока', 'пакет молока'), ('шариковых ручек', 'ручка'),
                          ('букетов ромашек', 'букет')])
        num_w = {3: 'трёх', 4: 'четырёх', 5: 'пяти', 6: 'шести', 7: 'семи', 8: 'восьми'}[n]
        q = (f'Расплачиваясь за покупку {num_w} {thing[0]}, {w.n} {w.v("отдал")} {rub(X)} и {w.v("получил")} {rub(C)} сдачи. '
             f'Сколько рублей стоит {"одна" if thing[1] == "ручка" else "один" if thing[1] in ("пакет молока", "букет") else "одно"} '
             f'{thing[1]}?')
        e = f'({X} − {C}) : {n} = {p}.'
        chk = lambda: (X - C) % n == 0 and (X - C) // n == ans
    elif st == 2:
        p = r.randint(45, 130)
        a, b = r.randint(50, 150), r.randint(60, 200)
        S = 2 * p + a + b
        ans = p
        things = r.choice([('две пачки творога', 'пачка творога', 'батон', 'банку мёда'),
                           ('два пакета кефира', 'пакет кефира', 'багет', 'коробку конфет'),
                           ('две плитки шоколада', 'плитка шоколада', 'пакет яблок', 'бутылку морса')])
        q = (f'{w.n} {w.v("купил")} в магазине {things[0]}, {things[2]} за {rub(a)} и {things[3]} за {rub(b)}. После оплаты банковской '
             f'картой пришло сообщение, что с карты списано {rub(S)}. Сколько рублей стоит {"одна" if things[1].startswith(("пачка", "плитка")) else "один"} '
             f'{things[1]}?')
        e = f'({S} − {a} − {b}) : 2 = {p}.'
        chk = lambda: F(S - a - b, 2) == ans
    else:
        c = F(r.choice([F(3, 2), F(5, 2), F(7, 2), F(9, 2), 3, 4]))
        mins = r.randint(6, 40)
        B = r.randint(int(c * mins) + 5, int(c * mins) + 150)
        R_ = B - c * mins
        if R_.denominator != 1 or R_ <= 0:
            return None
        ans = mins
        q = (f'На счёте телефона {w.g} было {rub(B)}, а после междугороднего разговора осталось {rub(R_)}. Разговор длился целое '
             f'число минут, минута стоит {rub(c)}. Сколько минут длился разговор?')
        e = f'({B} − {T(R_)}) : {dec(c)} = {mins}.'
        chk = lambda: F(B - R_) / F(c) == ans
    return pcard(q, num(ans), e=e), chk


@P('eb01-compare', 'Проездной (абонемент, подписка) или разовые покупки: разница',
   'Сравниваем стоимость разовых покупок (цена × число раз) со стоимостью абонемента и находим разность.',
   'Проездной, абонемент в бассейн, подписка на журнал, ски-пасс; цены, число посещений.',
   'n·s − S',
   r'проездного билета|полугодовой подписки',
   ['вычли в обратном порядке', 'забыли умножить разовую цену на число раз'],
   'Вопрос «На сколько рублей больше (меньше) …», ответ — целое число.')
def gen_eb01_compare(r):
    st = r.randrange(4)
    w = Who(r)
    if st == 0:
        s, n = r.randint(38, 72), r.randint(35, 60)
        S = r.choice(range(1400, 2600, 10))
        q = (f'Месячный проездной на автобус стоит {rub(S)}, а одна поездка без проездного — {rub(s)}. {w.n} {w.v("купил")} '
             f'проездной и за месяц {w.v("совершил")} {pl(n, "поездку", "поездки", "поездок")}. На сколько рублей больше '
             f'{"он потратил" if w.male else "она потратила"} бы, если бы оплачивал{"" if w.male else "а"} каждую поездку отдельно?')
    elif st == 1:
        s, n = r.choice(range(300, 700, 50)), r.randint(8, 16)
        S = r.choice(range(2400, 5200, 100))
        q = (f'Абонемент в бассейн на месяц стоит {rub(S)}, а разовое посещение — {rub(s)}. {w.n} {w.v("купил")} абонемент и за '
             f'месяц {w.v("сходил")} в бассейн {pl(n, "раз", "раза", "раз")}. На сколько рублей больше пришлось бы заплатить за '
             f'разовые посещения?')
    elif st == 2:
        s, n = r.randint(55, 120), r.randint(10, 24)
        S = r.choice(range(600, 1600, 20))
        q = (f'Годовая подписка на научно-популярный журнал стоит {rub(S)}, а один номер в киоске — {rub(s)}. За год {w.n} '
             f'{w.v("купил")} в киоске {pl(n, "номер", "номера", "номеров")} журнала. На сколько рублей меньше {"он потратил" if w.male else "она потратила"} '
             f'бы, если бы оформил{"" if w.male else "а"} подписку?')
    else:
        s, n = r.choice(range(1200, 2600, 100)), r.randint(4, 9)
        S = r.choice(range(5000, 12000, 500))
        q = (f'Ски-пасс на неделю стоит {rub(S)}, а подъёмы на один день — {rub(s)}. {w.n} {w.v("купил")} ски-пасс на неделю и '
             f'катал{"ся" if w.male else "ась"} {pl(n, "день", "дня", "дней")}. На сколько рублей больше пришлось бы заплатить, '
             f'если бы {w.n} покупал{"" if w.male else "а"} подъёмы на каждый день отдельно?')
    ans = n * s - S
    if ans <= 0:
        return None

    def chk():
        tot = 0
        for _ in range(n):
            tot += s
        return tot - S == ans
    return pcard(q, num(ans), e=f'{s} · {n} = {s * n}; {s * n} − {S} = {ans}.'), chk


@P('eb01-meter', 'Оплата по показаниям счётчика',
   'Расход — разность показаний; умножаем его на тариф.',
   'Горячая/холодная вода, электроэнергия, газ; даты, показания (с десятыми), тариф в рублях и копейках.',
   '(b − a)·t',
   r'прибор учёта|показания счётчика',
   ['умножили на тариф одно из показаний', 'ошиблись с копейками'],
   'Вопрос «Сколько рублей нужно заплатить за …», «Ответ дайте в рублях», тариф в руб. и коп.')
def gen_eb01_meter(r):
    st = r.randrange(4)
    months = [('1 февраля', '1 марта', 'февраль'), ('1 марта', '1 апреля', 'март'), ('1 сентября', '1 октября', 'сентябрь'),
              ('1 октября', '1 ноября', 'октябрь'), ('1 ноября', '1 декабря', 'ноябрь'), ('1 мая', '1 июня', 'май')]
    d1, d2, mon = r.choice(months)
    if st == 0:
        a = F(r.randint(200, 990), 10)
        u = F(r.choice([5, 6, 8, 10, 12, 14, 15, 16, 25]), 2)
        t = F(r.randint(18000, 26000), 100)
        what, unit, res = 'горячей воды', 'куб. м', 'горячую воду'
    elif st == 1:
        a = F(r.randint(1000, 9000), 10)
        u = F(r.choice([30, 40, 50, 60, 80, 90, 100, 120]), 2)
        t = F(r.randint(3000, 6500), 100)
        what, unit, res = 'холодной воды', 'куб. м', 'холодную воду'
    elif st == 2:
        a = r.randint(10000, 40000)
        u = r.choice([120, 150, 180, 200, 240, 250, 300, 320])
        t = F(r.randint(450, 850), 100)
        what, unit, res = 'электроэнергии', 'кВт·ч', 'электроэнергию'
    else:
        a = F(r.randint(1000, 8000), 10)
        u = F(r.choice([30, 40, 45, 50, 60, 70, 80]), 2)
        t = F(r.randint(700, 1100), 100)
        what, unit, res = 'газа', 'куб. м', 'газ'
    b = a + u
    ans = u * t
    if not nice(ans, 2, 100000):
        return None
    q = (f'{d1.capitalize()} счётчик {what} в квартире показывал {T(a)} {unit}, а {d2} — {T(b)} {unit}. Тариф составляет '
         f'{rub(t)} за 1 {unit}. Какую сумму нужно внести за {res}, израсходованн{"ую" if res != "газ" and res != "электроэнергию" else ("ый" if res == "газ" else "ую")} '
         f'в течение месяца? Ответ дайте в рублях.')

    def chk():
        return same(num(ans), (R(b) - R(a)) * R(t))
    return pcard(q, num(ans), e=f'Расход {T(b)} − {T(a)} = {T(u)} {unit}; {T(u)} · {T(t)} = {T(ans)}.'), chk


@P('eb01-fuel-cost', 'Расходы на топливо по расходу на 100 км',
   'Литры = расстояние · расход / 100; стоимость = литры · цена литра.',
   'Таксист, курьер, фургон доставки, поездки на дачу; пробег, расход, цена.',
   's·c/100·p',
   r'расход бензина на 100 км|средний расход',
   ['не разделили на 100', 'перепутали расход и цену'],
   'Вопрос «Сколько рублей потрачено на бензин (топливо) …», ответ — целое число.')
def gen_eb01_fuel_cost(r):
    st = r.randrange(4)
    c = r.choice([6, 7, 8, 9, 10, 11, 12, 14])
    p = r.randint(52, 70)
    if st == 0:
        s = r.choice(range(4000, 16000, 500))
        q = (f'За месяц таксист проехал {T(s)} км. Его автомобиль в среднем расходует {pl(c, "литр", "литра", "литров")} бензина на '
             f'100 км, литр бензина стоит {rub(p)}. Сколько рублей таксист потратил на бензин за месяц?')
    elif st == 1:
        s = r.choice(range(1200, 5000, 100))
        q = (f'Курьер за неделю проехал на машине {T(s)} км. Средний расход топлива его машины — {pl(c, "литр", "литра", "литров")} '
             f'на 100 км пути, цена топлива — {rub(p)} за литр. Сколько рублей стоило топливо, израсходованное за неделю?')
    elif st == 2:
        c = r.choice([12, 13, 14, 15, 16, 18])
        s = r.choice(range(2000, 9000, 100))
        q = (f'Фургон службы доставки расходует в среднем {pl(c, "литр", "литра", "литров")} дизельного топлива на 100 км. За месяц '
             f'он проехал {T(s)} км. Литр дизельного топлива стоит {rub(p)}. Сколько рублей потрачено на топливо за месяц?')
    else:
        s1 = r.choice(range(40, 160, 5))
        trips = r.randint(8, 20)
        s = s1 * 2 * trips
        q = (f'Дача находится в {pl(s1, "километре", "километрах", "километрах")} от дома. За лето семья {pl(trips, "раз", "раза", "раз")} '
             f'съездила на дачу и обратно. Машина расходует {pl(c, "литр", "литра", "литров")} бензина на 100 км, литр стоит {rub(p)}. '
             f'Сколько рублей потрачено на бензин для этих поездок?')
    ans = F(s * c, 100) * p
    if ans.denominator != 1:
        return None

    def chk():
        litres = R(s) / 100 * c
        return same(num(ans), litres * p)
    return pcard(q, num(ans), e=f'{T(s)} · {c} / 100 = {T(F(s * c, 100))} л; · {p} = {T(ans)}.'), chk


@P('eb01-convert', 'Перевод из неметрических единиц (с округлением)',
   'Умножаем (или делим) величину на коэффициент перевода и, если сказано, округляем до целого.',
   'Мили/футы/дюймы/фунты; сюжеты: спидометр, высота полёта, диагональ экрана, рецепт; направление перевода.',
   'x·k (округление до целого) или x / k',
   r'мил[иья]|фут',
   ['округлили не по правилам', 'перепутали умножение и деление'],
   'Коэффициент дан в условии («Считайте, что 1 миля равна 1609 м»), «Ответ округлите до целого числа».')
def gen_eb01_convert(r):
    st = r.randrange(7)
    if st == 5:
        x = r.randint(8, 35)
        val = F(x * 1852, 1000)
        q = (f'Скорость морских судов измеряют в узлах: 1 узел равен 1,852 км/ч. Паром идёт со скоростью {pl(x, "узел", "узла", "узлов")}. '
             f'Какова его скорость в километрах в час? Ответ округлите до целого числа.')
    elif st == 6:
        x = r.choice(range(40, 131, 5))
        val = F(x * 9144, 10000)
        q = (f'На табло стадиона в Лондоне длина удара в регби указана в ярдах: {pl(x, "ярд", "ярда", "ярдов")}. Сколько это метров, '
             f'если в одном ярде 0,9144 м? Ответ округлите до целого числа.')
    elif st == 0:
        x = r.randint(20, 75)
        val = F(x * 1609, 1000)
        q = (f'Путешественник взял напрокат машину в Канзасе, и шкала её спидометра размечена в милях. Стрелка стоит на отметке {x}. '
             f'С какой скоростью (в км/ч) едет машина? Примите, что в одной миле 1609 метров. Ответ округлите до целого числа.')
    elif st == 1:
        x = r.choice(range(12000, 38000, 500))
        val = F(x * 305, 1000)
        q = (f'Командир экипажа объявил, что лайнер летит на эшелоне {T(x)} футов. На какой высоте (в метрах) летит лайнер, если '
             f'в одном футе 30,5 сантиметра? Ответ округлите до целого числа.')
    elif st == 2:
        x = r.choice([32, 40, 43, 50, 55, 58, 65, 75, 85])
        val = F(x * 254, 100)
        q = (f'Диагональ экрана телевизора равна {pl(x, "дюйму", "дюймам", "дюймам")}. Выразите диагональ экрана в сантиметрах, '
             f'если 1 дюйм равен 2,54 см. Ответ округлите до целого числа.')
    elif st == 3:
        x = r.choice([2, 3, 4, 5, 6, 7, 8, 9, 11, 12, 15])
        val = F(x * 454, 1000)
        q = (f'В английском рецепте пирога указано {pl(x, "фунт", "фунта", "фунтов")} сахара. Сколько килограммов сахара нужно взять, '
             f'если 1 фунт равен 0,454 кг? Ответ округлите до десятых.')
        frac = val * 10 - floor(val * 10)
        if F(4, 10) < frac < F(6, 10):
            return None
        ans = F(floor(val * 10 + F(1, 2)), 10)

        def chk():
            return abs(float(R(val)) - float(ans)) <= 0.05 and same(num(ans), sp.Rational(round(float(R(val)) * 10), 10))
        return pcard(q, num(ans), e=f'{x} · 0,454 = {dec(val)} ≈ {dec(ans)}.'), chk
    else:
        kmh = r.choice(range(40, 130, 8))
        val = F(kmh, 1) / F(8, 5)
        if val.denominator != 1:
            return None
        ans = val
        q = (f'Навигатор показывает, что машина идёт со скоростью {kmh} км/ч, а шкала её спидометра, привезённого из Англии, '
             f'проградуирована в милях в час. Какое значение показывает спидометр, если одна миля — это 1,6 км?')

        def chk():
            return same(num(ans), sp.Rational(kmh) * 5 / 8)
        return pcard(q, num(ans), e=f'{kmh} : 1,6 = {num(ans)}.'), chk
    frac = val - floor(val)
    if F(4, 10) < frac < F(6, 10):
        return None
    ans = floor(val + F(1, 2))

    def chk():
        return abs(float(R(val)) - ans) < 0.5 and same(num(ans), sp.floor(R(val) + sp.Rational(1, 2)))
    return pcard(q, num(ans), e=f'{dec(val)} ≈ {ans}.'), chk


@P('eb01-proportion', 'Пропорциональные величины: путь за время, файл, насос',
   'При постоянной скорости величина пропорциональна времени: находим её за единицу времени и умножаем.',
   'Велосипедист, пешеход, загрузка файла, насос, принтер; числа подобраны так, что ответ — конечная дробь.',
   'b·t2 / t1',
   r'если будет (ехать|идти) с той же скоростью|скорость загрузки останется прежней',
   ['перевернули пропорцию', 'не перевели часы в минуты'],
   'Вопрос «Сколько километров он проедет за … минут, если будет ехать с той же скоростью?»')
def gen_eb01_proportion(r):
    st = r.randrange(4)
    t1 = r.choice([10, 12, 15, 16, 20, 24, 25, 30, 40, 45])
    t2 = r.choice([12, 18, 20, 25, 27, 35, 36, 50, 54, 60])
    if t1 == t2:
        return None
    if st == 0:
        a = r.choice([2, 3, 4, 5, 6, 7, 8, 9, 10, 12])
        ans = F(a * t2, t1)
        q = (f'За {pl(t1, "минуту", "минуты", "минут")} велосипедист преодолел {pl(a, "километр", "километра", "километров")}. '
             f'Какое расстояние (в километрах) он преодолеет за {pl(t2, "минуту", "минуты", "минут")}, не меняя скорости?')
    elif st == 1:
        a = r.choice([F(3, 2), 2, F(5, 2), 3, F(7, 2), 4])
        ans = F(a) * t2 / t1
        q = (f'Двигаясь по тропе в одном темпе, турист за {pl(t1, "минуту", "минуты", "минут")} прошёл {dec(a)} км. Сколько '
             f'километров он пройдёт в том же темпе за {pl(t2, "минуту", "минуты", "минут")}?')
    elif st == 2:
        a = r.choice([120, 150, 180, 240, 300, 360, 450, 600, 720])
        ans = F(a * t2, t1)
        q = (f'Архив размером {a} Мбайт загрузился за {pl(t1, "секунду", "секунды", "секунд")}. Сколько мегабайт загрузится за '
             f'{pl(t2, "секунду", "секунды", "секунд")}, если скорость загрузки не изменится?')
    else:
        a = r.choice([60, 75, 90, 120, 150, 180, 240])
        ans = F(a * t2, t1)
        q = (f'Насос за {pl(t1, "минуту", "минуты", "минут")} перекачивает {pl(a, "литр", "литра", "литров")} воды. Сколько литров '
             f'воды он перекачает за {pl(t2, "минуту", "минуты", "минут")}, если будет работать так же?')
    if not nice(ans, 2) or ans.denominator > 4:
        return None

    def chk():
        v = sp.Rational(1, 1) * R(F(ans)) / t2  # скорость из ответа совпадает со скоростью из условия
        return sp.simplify(v - R(F(a)) / t1) == 0
    return pcard(q, num(ans), e=f'За минуту (секунду): {dec(a)} / {t1}; за {t2}: {dec(a)} · {t2} / {t1} = {num(ans)}.'), chk


@P('eb01-duration', 'Время в пути по расписанию (через полночь)',
   'Время до полуночи плюс время после полуночи.',
   'Поезд, паром, междугородний автобус, ночной рейс; города и время отправления/прибытия.',
   '24 − t1 + t2 (в часах)',
   r'отправляется в \d+:\d+.*прибывает',
   ['вычли время прибытия из времени отправления', 'забыли про смену суток'],
   'Вопрос «Сколько часов … находится в пути?», время по одному часовому поясу.')
def gen_eb01_duration(r):
    h1 = r.randint(8, 23)
    m = r.choice([0, 5, 12, 17, 25, 30, 38, 44, 50, 57])
    dur = r.randint(6, 22)
    h2 = (h1 + dur) % 24
    if h1 + dur < 24:
        return None
    st = r.randrange(4)
    t1, t2 = f'{h1}:{m:02d}', f'{h2}:{m:02d}'
    if st == 0:
        a, b = r.choice([('Екатеринбург', 'Тюмень'), ('Казань', 'Самара'), ('Воронеж', 'Ростов-на-Дону'), ('Пермь', 'Киров'),
                         ('Омск', 'Томск')])
        q = (f'Скорый поезд {a} — {b} уходит в {t1}, а к конечной станции подходит в {t2} уже следующих суток. Всё время в '
             f'расписании указано по одному часовому поясу. Сколько часов длится поездка?')
    elif st == 1:
        q = (f'Паром отходит от причала в {t1} и приходит в порт назначения в {t2} следующего дня (время местное, часовой пояс '
             f'не меняется). Сколько часов длится переправа?')
    elif st == 2:
        q = (f'Междугородний автобус выезжает с автовокзала в {t1} и прибывает на конечную остановку в {t2} следующего дня. Оба '
             f'города находятся в одном часовом поясе. Сколько часов автобус находится в пути?')
    else:
        q = (f'По расписанию речного круиза теплоход отчаливает в {t1}, а швартуется у следующей пристани в {t2} наутро '
             f'(обе отметки — по московскому времени). Сколько часов теплоход идёт до следующей пристани?')
    ans = dur

    def chk():
        t = h1 * 60 + m
        steps = 0
        while t % (24 * 60) != (h2 * 60 + m) or steps == 0:
            t += 60
            steps += 1
        return steps == ans
    return pcard(q, num(ans), e=f'До полуночи {24 * 60 - h1 * 60 - m} мин, после — {h2 * 60 + m} мин; всего {ans} ч.'), chk


@P('eb01-payback', 'Окупаемость: через сколько месяцев экономия превысит затраты',
   'Ежемесячная экономия — разность платежей; ищем наименьшее целое число месяцев, при котором накопленная экономия больше затрат.',
   'Светодиодные лампы, фильтр для воды, утепление окон, кофемашина; цены и платежи.',
   'наименьшее m: m·(B − A) > C',
   r'экономия .*превысит',
   ['взяли частное без округления', 'остановились на равенстве вместо «превысит»'],
   'Вопрос «Через какое наименьшее количество месяцев экономия превысит затраты …»')
def gen_eb01_payback(r):
    st = r.randrange(4)
    if st == 0:
        B = r.choice(range(900, 2200, 50))
        A = B - r.choice(range(150, 700, 50))
        C = r.choice(range(2400, 6000, 100))
        q = (f'Замена всех ламп в квартире на светодиодные обошлась в {rub(C)}. До замены за электроэнергию платили {rub(B)} в месяц, '
             f'после замены — {rub(A)} в месяц. Через какое наименьшее число месяцев экономия на оплате электроэнергии превысит '
             f'затраты на замену ламп, если тарифы не изменятся?')
    elif st == 1:
        B = r.choice(range(800, 1600, 50))
        A = r.choice(range(100, 300, 20))
        C = r.choice(range(3500, 9000, 100))
        q = (f'Семья тратила на покупку питьевой воды в бутылках {rub(B)} в месяц. Установили фильтр за {rub(C)}, после этого на '
             f'сменные картриджи уходит {rub(A)} в месяц. Через какое наименьшее число месяцев экономия превысит стоимость фильтра?')
    elif st == 2:
        B = r.choice(range(2600, 4500, 100))
        A = B - r.choice(range(300, 1100, 100))
        C = r.choice(range(9000, 25000, 500))
        q = (f'Утепление окон в доме стоило {rub(C)}. До утепления отопление обходилось в {rub(B)} в месяц, после — в {rub(A)} в месяц. '
             f'Через какое наименьшее количество месяцев отопительного сезона экономия превысит затраты на утепление, если тарифы не '
             f'изменятся?')
    else:
        B = r.choice(range(2500, 5000, 100))
        A = r.choice(range(700, 1500, 100))
        C = r.choice(range(12000, 30000, 1000))
        q = (f'Офис покупал кофе в кофейне на {rub(B)} в месяц. Затем купили кофемашину за {rub(C)}, и теперь кофейные зёрна обходятся '
             f'в {rub(A)} в месяц. Через какое наименьшее число месяцев экономия превысит стоимость кофемашины?')
    d = B - A
    if d <= 0:
        return None
    ans = C // d + 1
    if ans < 3 or ans > 60:
        return None

    def chk():
        m, saved = 0, 0
        while saved <= C:
            m += 1
            saved += B - A
        return m == ans
    return pcard(q, num(ans), e=f'Экономия {d} руб. в месяц; {C} : {d} ≈ {ap(F(C, d))}; нужно больше — {ans}.'), chk


@P('eb01-daily-charge', 'Ежедневное списание: на сколько дней хватит денег',
   'Каждый день списывается одна и та же сумма; услуга доступна, пока на счёте хватает на списание — берём целую часть частного.',
   'Тариф связи, онлайн-кинотеатр, школьная карта для обедов, аренда самоката; сумма и списание.',
   'floor(B / d)',
   r'каждый вечер снимает со счёта',
   ['округлили вверх', 'прибавили лишний день'],
   'Вопрос «Сколько дней (включая сегодняшний) можно пользоваться …»')
def gen_eb01_daily_charge(r):
    st = r.randrange(4)
    w = Who(r)
    d = r.choice([7, 9, 11, 12, 13, 14, 15, 17, 19, 23, 25])
    B = r.choice(range(150, 900, 10))
    if B % d == 0:
        return None
    if st == 0:
        q = (f'По тарифу «Ежедневный» оператор связи каждый вечер списывает со счёта абонента {rub(d)}. Если после списания на счёте '
             f'остаётся меньше {rub(d)}, то со следующего утра связь отключают до пополнения. Утром на счёте у {w.g} было {rub(B)}. '
             f'Сколько дней (считая сегодняшний) {w.n} сможет пользоваться связью, не пополняя счёт?')
    elif st == 1:
        q = (f'Онлайн-кинотеатр каждый вечер снимает с баланса подписчика {rub(d)}. Если после этого на балансе меньше {rub(d)}, то '
             f'наутро доступ к фильмам закрывается до пополнения. Сегодня утром на балансе у {w.g} {rub(B)}. Сколько дней (включая '
             f'сегодняшний) {w.n} сможет смотреть фильмы без пополнения баланса?')
    elif st == 2:
        d = r.choice([85, 90, 95, 105, 110, 120, 125, 135])
        B = r.choice(range(900, 3500, 50))
        if B % d == 0:
            return None
        q = (f'Каждый учебный день со школьной карты {w.g} списывается {rub(d)} за обед. Если на карте меньше {rub(d)}, обед не '
             f'выдают. На карте {rub(B)}. На сколько учебных дней хватит этих денег, если карту не пополнять?')
    else:
        d = r.choice([150, 180, 190, 210, 240, 260])
        B = r.choice(range(1000, 5000, 100))
        if B % d == 0:
            return None
        q = (f'Сервис проката самокатов каждый вечер списывает со счёта пользователя {rub(d)} за суточный абонемент. Если после '
             f'списания на счёте меньше {rub(d)}, то наутро абонемент не продлевается. Утром на счёте {w.g} было {rub(B)}. Сколько '
             f'дней (включая сегодняшний) {w.n} сможет пользоваться самокатами без пополнения счёта?')
    ans = B // d

    def chk():
        bal, days = B, 0
        while bal >= d:
            days += 1
            bal -= d
        return days == ans
    return pcard(q, num(ans), e=f'{B} : {d} = {B // d} (ост. {B % d}) — {ans} дней.'), chk


@P('eb01-apartment', 'Этаж или подъезд по номеру квартиры',
   'Квартиры нумеруются подряд: делим номер на число квартир на этаже (в подъезде) и округляем вверх.',
   'Число квартир на этаже, этажность, номер квартиры; вопрос про этаж или подъезд; жилой дом, общежитие, гостиница.',
   'ceil(n / q) или ceil(n / (q·F))',
   r'живёт в квартире № \d+\. (На каком этаже|В каком подъезде)',
   ['округлили вниз', 'разделили на число этажей, а не квартир в подъезде'],
   'Вопрос «На каком этаже / в каком подъезде живёт …», ответ — целое число.')
def gen_eb01_apartment(r):
    w = Who(r)
    if r.random() < 0.5:
        q_ = r.choice([4, 5, 6, 7, 8])
        n = r.randint(q_ + 1, 16 * q_)
        if n % q_ == 0:
            return None
        ans = ceil(n, q_)
        if r.random() < 0.5:
            q = (f'Дом, где поселилась семья {w.g}, одноподъездный, на каждом этаже по {pl(q_, "квартире", "квартиры", "квартир")}. '
                 f'Номер их квартиры — {n}. На каком этаже расположена эта квартира?')
        else:
            q = (f'В студенческом общежитии на каждом этаже по {pl(q_, "комнате", "комнаты", "комнат")}, комнаты пронумерованы подряд, '
                 f'начиная с первого этажа. {w.n} живёт в комнате № {n}. На каком этаже находится эта комната?')
        e = f'{n} : {q_} = {dec(F(n, q_)) if finite(F(n, q_)) else f"{n // q_} (ост. {n % q_})"} → этаж {ans}.'

        def chk():
            return (n - 1) // q_ + 1 == ans
    else:
        fl = r.choice([5, 9, 10, 12, 14, 16, 17])
        q_ = r.choice([3, 4, 5, 6])
        per = fl * q_
        n = r.randint(per + 1, 6 * per)
        if n % per == 0:
            return None
        ans = ceil(n, per)
        q = (f'В доме {fl} {plural(fl, "этаж", "этажа", "этажей")} и несколько подъездов, на каждом этаже по {pl(q_, "квартире", "квартиры", "квартир")}, '
             f'нумерация квартир сквозная, с первого подъезда. Друзья {w.g} живут в квартире № {n}. В каком подъезде находится их квартира?')
        e = f'В подъезде {fl} · {q_} = {per} квартир; {n} : {per} → подъезд {ans}.'

        def chk():
            flat = 0
            for ent in range(1, 50):
                for _ in range(per):
                    flat += 1
                    if flat == n:
                        return ent == ans
            return False
    return pcard(q, num(ans), e=e), chk


@P('eb01-sets-cost', 'Стоимость наборов: большинству по одному, некоторым по-другому',
   'Число «обычных» наборов = всего − особых («включая»); считаем количество штук и умножаем на цену.',
   'Букеты учителям, подарочные наборы команде, шары группам; число получателей, размеры наборов, цена.',
   '((T − s)·a + s·b)·p',
   r'букеты цветов для последнего звонка',
   ['не вычли особых получателей из общего числа («включая»)', 'умножили цену только на число наборов'],
   'Вопрос «Сколько рублей стоят все …», ответ — целое число.')
def gen_eb01_sets_cost(r):
    st = r.randrange(3)
    T_ = r.randint(12, 30)
    a, b = r.choice([(3, 7), (5, 9), (5, 11), (3, 9), (7, 15)])
    s = r.choice([2, 3])
    p = r.randint(20, 90)
    two = {2: 'двум', 3: 'трём'}[s]
    if st == 0:
        q = (f'Родительский комитет заказывает цветы к Дню учителя: по {a} хризантем каждому учителю, а завучу и директору — по {b} '
             f'хризантем. Всего нужно поздравить {pl(T_, "учителя", "учителей", "учителей")} (включая завуча и директора). Хризантемы '
             f'продаются по {rub(p)} за штуку. Сколько рублей стоят все хризантемы?')
        s = 2
    elif st == 1:
        q = (f'Для участников турнира готовят сувенирные наборы: каждому игроку — по {a} значков, а капитану, вице-капитану и тренеру — '
             f'по {b} значков. Всего наборов {T_} (капитан, вице-капитан и тренер входят в это число). Значок стоит {rub(p)}. Сколько '
             f'рублей стоят все значки?')
        s = 3
    else:
        q = (f'К празднику в детском саду покупают воздушные шары: по {a} шаров в каждую группу, а {two} самым большим группам — по {b} '
             f'шаров. Всего в детском саду {pl(T_, "группа", "группы", "групп")} (включая самые большие). Шар стоит {rub(p)}. Сколько '
             f'рублей стоят все шары?')
    ans = ((T_ - s) * a + s * b) * p

    def chk():
        cnt = sum(b if i < s else a for i in range(T_))
        return cnt * p == ans
    return pcard(q, num(ans), e=f'Штук: ({T_} − {s}) · {a} + {s} · {b} = {(T_ - s) * a + s * b}; · {p} = {ans}.'), chk


@P('eb01-speed', 'Средняя скорость в км/ч по метрам и секундам',
   'Скорость в м/с = метры / секунды; переводим в км/ч умножением на 3,6.',
   'Бегун, пловец, конькобежец, велосипедист на треке; дистанция и время.',
   'd / t · 3,6',
   r'пробежал .*Ответ дайте в километрах в час',
   ['забыли перевести в км/ч', 'умножили на 60 вместо 3,6'],
   '«Найдите среднюю скорость … Ответ дайте в километрах в час.»')
def gen_eb01_speed(r):
    st = r.randrange(4)
    v = F(r.choice([range(12, 31), range(3, 9), range(25, 46), range(30, 61)][st]))
    t = r.choice([10, 12, 15, 18, 20, 24, 25, 30, 36, 40, 45, 48, 50, 54, 60, 72, 75, 80, 90, 100, 120])
    d = v / F(18, 5) * t
    if d.denominator != 1 or d > 3000 or d < 50:
        return None
    ans = v
    if st == 0:
        q = (f'На тренировке спортсменка пробежала отрезок в {d} м, и секундомер показал {pl(t, "секунду", "секунды", "секунд")}. '
             f'С какой средней скоростью она бежала? Ответ дайте в километрах в час.')
    elif st == 1:
        q = (f'В бассейне пловец преодолел {d} м за {pl(t, "секунду", "секунды", "секунд")}. С какой средней скоростью он плыл? '
             f'Ответ дайте в километрах в час.')
    elif st == 2:
        q = (f'Конькобежец прошёл отрезок {d} м за {pl(t, "секунду", "секунды", "секунд")}. Какой была его средняя скорость на '
             f'этом отрезке? Ответ дайте в километрах в час.')
    else:
        q = (f'На треке велогонщик проехал {d} м за {pl(t, "секунду", "секунды", "секунд")}. С какой средней скоростью '
             f'он ехал? Ответ дайте в километрах в час.')

    def chk():
        return same(num(ans), sp.Rational(int(d), 1000) / (sp.Rational(t, 3600)))
    return pcard(q, num(ans), e=f'{d} м : {t} с = {ftxt(F(int(d), t))} м/с; · 3,6 = {num(ans)} км/ч.'), chk


@P('eb01-scale', 'Масштаб карты (плана)',
   'Расстояние на местности = расстояние на карте × число километров (метров) в 1 см; обратная задача — деление.',
   'Карта области, туристическая схема, план парка; прямое и обратное направление.',
   'k·x или y / k',
   r'Масштаб карты',
   ['перепутали умножение и деление', 'не учли единицы (м/км)'],
   'Вопрос «Чему равно расстояние … (в км)», ответ — число.')
def gen_eb01_scale(r):
    st = r.randrange(4)
    k = r.choice([F(1, 2), F(3, 2), 2, F(5, 2), 3, 4, 5, F(11, 2), 8, 10, 12, 15, 25])
    x = r.choice([F(3, 2), 2, F(5, 2), 3, F(7, 2), 4, F(9, 2), 5, 6, 7, F(15, 2), 8, 9, 11, 12, 14, 16])
    y = k * x
    if st == 0:
        q = (f'На карте области 1 см соответствует {dec(k)} км на местности. Расстояние между двумя сёлами на карте равно {dec(x)} см. '
             f'Каково расстояние между сёлами на местности? Ответ дайте в километрах.')
        ans = y
    elif st == 1:
        q = (f'На туристической схеме в одном сантиметре {dec(k)} км. Длина маршрута на местности {dec(y)} км. Какова длина этого '
             f'маршрута на схеме? Ответ дайте в сантиметрах.')
        ans = x
    elif st == 2:
        k = r.choice([5, 10, 20, 25, 40, 50])
        y = k * x
        q = (f'На плане парка 1 см соответствует {k} м. Длина аллеи на плане {dec(x)} см. Найдите длину аллеи на самом деле. Ответ '
             f'дайте в метрах.')
        ans = y
    else:
        q = (f'Масштаб дорожной карты такой, что 1 см на карте соответствует {dec(k)} км. Между двумя городами по прямой {dec(y)} км. '
             f'Сколько сантиметров между ними на карте?')
        ans = x
    if not nice(ans, 2):
        return None

    def chk():
        return same(num(ans), R(y) / R(k) if ans == x and st in (1, 3) else R(k) * R(x))
    return pcard(q, num(ans), e=f'Масштаб: 1 см — {dec(k)}; ответ {num(ans)}.'), chk


